#!/usr/bin/env python3
"""Verifier for p010: the Mona Lisa 100,000-city traveling salesman instance.

Contract (shared by every problem):
    python verify.py <shot_dir>
Reads <shot_dir>/certificate.json and prints exactly one line of JSON to stdout:
    {"valid": bool, "score": "exact rational string" | null,
     "canonical_hash": "sha256 hex of the canonical certificate" | null, "message": str}
Exit code 0 means a verdict was given (valid or not); non-zero means a usage or configuration error.

Safety: parses JSON and integers only; no eval, pickle, yaml or symbolic maths; no network;
never echoes strings from the input. Python 3.12 standard library only.

Rule: a tour visits each of the 100,000 cities of mona-lisa100K.tsp (Bosch, 2009) exactly once
and returns to its start. Cities are numbered 1..100000 as in the TSPLIB file. The distance between
two cities is the TSPLIB EUC_2D distance nint(sqrt(dx^2 + dy^2)), computed exactly with integers.
Score = tour length. Lower is better.

Instance data: the coordinates are embedded below (COORDS_B85), as base85 of the zlib-compressed
sequence x1, y1, x2, y2, ..., x100000, y100000 of unsigned 16-bit little-endian integers. The
sha256 of the decompressed bytes is checked before use. The source file mona-lisa100K.tsp
(https://www.math.uwaterloo.ca/tsp/data/ml/mona-lisa100K.tsp) has sha256
532fefbfb9ad66cc2550bece766fa069acaa8e34ee511ac1949ae101da4d70ad; test_verify.py rebuilds that
file byte for byte from the embedded coordinates and checks this hash.
"""

from __future__ import annotations

import base64
import hashlib
import json
import math
import os
import stat
import struct
import sys
import tomllib
import zlib
from fractions import Fraction
from pathlib import Path

CERT_NAME = "certificate.json"
MAX_DEPTH = 8                 # maximum JSON nesting depth
MAX_INT_DIGITS = 18           # maximum digits in a single integer
N_CITIES = 100000
COORDS_SHA256 = "e08720e6660029d62a75d0793bc9a5825d2bf0ed05d77645a7351c1fd54603f2"


class Invalid(Exception):
    """The certificate is invalid. The message is shown verbatim, so it must not contain input strings."""


# ---------- configuration

def find_problem_toml() -> Path:
    here = Path(__file__).resolve().parent
    for cand in (here / "problem.toml", here.parent / "problem.toml"):
        if cand.is_file():
            return cand
    raise FileNotFoundError("problem.toml not found")


def load_config(path: Path | None = None) -> dict:
    with open(path or find_problem_toml(), "rb") as f:
        data = tomllib.load(f)
    cities = data["params"]["cities"]
    limit = data["max_certificate_bytes"]
    if type(cities) is not int or cities != N_CITIES:
        raise ValueError("params.cities must be 100000")
    if type(limit) is not int or not 1 <= limit <= 16 * 1024 * 1024:
        raise ValueError("max_certificate_bytes out of range")
    return {"cities": cities, "max_certificate_bytes": limit}


# ---------- instance data

_COORDS: tuple[tuple[int, ...], tuple[int, ...]] | None = None


def coordinates() -> tuple[tuple[int, ...], tuple[int, ...]]:
    """(xs, ys), each a tuple of 100000 integers; index i is city i + 1."""
    global _COORDS
    if _COORDS is None:
        raw = zlib.decompress(base64.b85decode(COORDS_B85))
        if len(raw) != 4 * N_CITIES or hashlib.sha256(raw).hexdigest() != COORDS_SHA256:
            raise RuntimeError("embedded instance data is corrupt")
        flat = struct.unpack(f"<{2 * N_CITIES}H", raw)
        _COORDS = (flat[0::2], flat[1::2])
    return _COORDS


def euc_2d(dx: int, dy: int) -> int:
    """TSPLIB EUC_2D: floor(sqrt(dx^2 + dy^2) + 0.5), exactly."""
    s = dx * dx + dy * dy
    r = math.isqrt(s)
    # sqrt(s) + 1/2 >= r + 1  <=>  s >= r^2 + r + 1/4  <=>  s > r^2 + r  (s, r integers)
    return r + 1 if s > r * r + r else r


# ---------- reading and parsing (shared)

def read_certificate(shot_dir: str | os.PathLike, limit: int) -> bytes:
    path = Path(shot_dir) / CERT_NAME
    flags = os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0) | getattr(os, "O_NONBLOCK", 0)
    try:
        fd = os.open(path, flags)
    except FileNotFoundError:
        raise Invalid("certificate.json is missing") from None
    except OSError:
        raise Invalid("cannot read certificate.json (symbolic links are not allowed)") from None
    with os.fdopen(fd, "rb") as f:
        st = os.fstat(f.fileno())
        if not stat.S_ISREG(st.st_mode):
            raise Invalid("certificate.json is not a regular file")
        if st.st_size > limit:
            raise Invalid(f"certificate.json exceeds the size limit of {limit} bytes")
        data = f.read(limit + 1)
    if len(data) > limit:
        raise Invalid(f"certificate.json exceeds the size limit of {limit} bytes")
    return data


def check_depth(text: str, limit: int = MAX_DEPTH) -> None:
    depth = 0
    in_str = esc = False
    for ch in text:
        if in_str:
            if esc:
                esc = False
            elif ch == "\\":
                esc = True
            elif ch == '"':
                in_str = False
        elif ch == '"':
            in_str = True
        elif ch in "[{":
            depth += 1
            if depth > limit:
                raise Invalid(f"JSON is nested deeper than {limit} levels")
        elif ch in "]}":
            depth -= 1


def _no_float(_s: str):
    raise Invalid("fractional or exponent numbers are not allowed")


def _no_constant(_s: str):
    raise Invalid("NaN and Infinity are not allowed")


def _bounded_int(s: str) -> int:
    if len(s.lstrip("-")) > MAX_INT_DIGITS:
        raise Invalid(f"an integer has more than {MAX_INT_DIGITS} digits")
    return int(s)


def _unique_keys(pairs: list) -> dict:
    out: dict = {}
    for k, v in pairs:
        if k in out:
            raise Invalid("a JSON object has duplicate keys")
        out[k] = v
    return out


def strict_json(data: bytes):
    try:
        text = data.decode("utf-8")
    except UnicodeDecodeError:
        raise Invalid("certificate.json must be UTF-8 text") from None
    check_depth(text)
    try:
        return json.loads(
            text,
            parse_float=_no_float,
            parse_int=_bounded_int,
            parse_constant=_no_constant,
            object_pairs_hook=_unique_keys,
        )
    except RecursionError:
        raise Invalid("JSON is nested too deeply") from None
    except ValueError:
        raise Invalid("certificate.json is not valid JSON") from None


def is_int(x) -> bool:
    return type(x) is int  # excludes bool


def canonical_hash(obj) -> str:
    blob = json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=True)
    return hashlib.sha256(blob.encode("ascii")).hexdigest()


# ---------- problem rule

def canonical_tour(tour: list) -> list:
    """Rotate so that city 1 comes first; of the two directions, keep the one whose second city is smaller."""
    k = tour.index(1)
    t = tour[k:] + tour[:k]
    if t[-1] < t[1]:
        t = [t[0]] + t[:0:-1]
    return t


def tour_length(tour: list) -> int:
    xs, ys = coordinates()
    total = 0
    prev = tour[-1] - 1
    px, py = xs[prev], ys[prev]
    for c in tour:
        cx, cy = xs[c - 1], ys[c - 1]
        total += euc_2d(cx - px, cy - py)
        px, py = cx, cy
    return total


def check_certificate(cert, cfg: dict) -> tuple[Fraction, dict]:
    """Returns (score, canonical object)."""
    n = cfg["cities"]
    if not isinstance(cert, dict) or set(cert) != {"tour"}:
        raise Invalid('the certificate must be a JSON object with the single key "tour"')
    tour = cert["tour"]
    if not isinstance(tour, list):
        raise Invalid("tour must be a list of city numbers")
    if len(tour) != n:
        raise Invalid(f"tour must list exactly {n} cities")
    seen = bytearray(n + 1)
    for c in tour:
        if not is_int(c):
            raise Invalid("each city must be a JSON integer")
        if not 1 <= c <= n:
            raise Invalid(f"city numbers must be between 1 and {n}")
        if seen[c]:
            raise Invalid("a city appears more than once")
        seen[c] = 1
    length = tour_length(tour)
    return Fraction(length), {"tour": canonical_tour(tour)}


# ---------- entry point

def verify_bytes(data: bytes, cfg: dict) -> dict:
    cert = strict_json(data)
    score, canon = check_certificate(cert, cfg)
    return {
        "valid": True,
        "score": str(score),
        "canonical_hash": canonical_hash(canon),
        "message": "ok",
    }


def verify_dir(shot_dir: str | os.PathLike, cfg: dict) -> dict:
    try:
        return verify_bytes(read_certificate(shot_dir, cfg["max_certificate_bytes"]), cfg)
    except Invalid as e:
        return invalid(str(e))
    except RecursionError:
        return invalid("JSON is nested too deeply")
    except MemoryError:
        return invalid("input is too large")
    except Exception:  # no traceback, to avoid leaking details
        return invalid("internal verifier error")


def invalid(message: str) -> dict:
    return {"valid": False, "score": None, "canonical_hash": None, "message": message}


def emit(result: dict) -> None:
    line = json.dumps(result, ensure_ascii=False, separators=(",", ":"))
    sys.stdout.buffer.write(line.encode("utf-8") + b"\n")
    sys.stdout.buffer.flush()


def main(argv: list[str]) -> int:
    if len(argv) != 2:
        emit(invalid("usage: python verify.py <shot_dir>"))
        return 2
    try:
        cfg = load_config()
        coordinates()
    except Exception:
        emit(invalid("verifier configuration error"))
        return 2
    emit(verify_dir(argv[1], cfg))
    return 0


